name: Backend E2E

# Multi-process backend end-to-end tests: real `mesh-talk-node` processes over UDP
# discovery + TCP (two-node DM, message history across restart, post-office offline
# delivery). These are `#[ignore]`d so the normal `cargo test` skips them; this workflow
# runs them explicitly via `make e2e`. They are fast + reliable in CI because the spawned
# binary builds with the `fast-test-kdf` feature (cheap argon2 in test builds only — the
# shipped binary is unaffected). The browser/UI E2E lives in `e2e-ui.yml`.
on:
  merge_group:
    types: [checks_requested]
  push:
    branches: ["main"]
  pull_request:
    branches: ["main"]
  schedule:
    - cron: "0 5 * * 3" # Wednesdays 05:00 UTC
  workflow_dispatch:

# Read-only: builds the core crate + node binary and runs the integration rigs.
permissions:
  contents: read

concurrency:
  group: ${{ github.workflow }}-${{ github.event_name }}-${{ github.event.pull_request.number || github.ref }}-${{ github.event_name == 'push' && github.run_id || 'candidate' }}
  cancel-in-progress: ${{ github.event_name == 'pull_request' || github.event_name == 'merge_group' }}

env:
  CARGO_TERM_COLOR: always
  CARGO_PROFILE_DEV_DEBUG: line-tables-only
  CARGO_PROFILE_TEST_DEBUG: line-tables-only

# Linux backend evidence is produced once by the instrumented CI workspace job.
jobs:
  scope:
    uses: ./.github/workflows/ci-scope.yml

  backend-platform:
    if: ${{ !cancelled() }}
    needs: [scope]
    name: Backend core (${{ matrix.os }})
    strategy:
      fail-fast: false
      matrix:
        os: [windows-2022, macos-26-intel]
    runs-on: ${{ needs.scope.outputs.full == 'true' && matrix.os || 'ubuntu-latest' }}
    timeout-minutes: 40
    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      # mesh-talk-core + the mesh-talk-node binary are UI-free (no GTK/WebKit needed).
        with:
          fetch-depth: 2
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: ${{ needs.scope.outputs.full }}
          upstream_result: ${{ needs.scope.result }}
      - name: Install Rust toolchain
        if: ${{ steps.scope.outputs.full == 'true' }}
        uses: dtolnay/rust-toolchain@stable

      - name: Install evidence runner
        if: ${{ steps.scope.outputs.full == 'true' }}
        uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: "22"

      - name: Cache Rust build
        if: ${{ steps.scope.outputs.full == 'true' }}
        uses: Swatinem/rust-cache@v2
        with:
          save-if: ${{ github.ref == 'refs/heads/main' }}

      - name: Configure hosted macOS multicast route
        if: ${{ steps.scope.outputs.full == 'true' && (runner.os == 'macOS') }}
        run: |
          sudo route -n add -host 224.0.0.167 -interface 127.0.0.1
          node scripts/diagnostics/native-multicast-probe.mjs --require

      # Native CLI processes, signed discovery, encrypted TCP, restart, relay,
      # channels and byte-for-byte file transfer; never pass on zero selected tests.
      - name: Run multi-process E2E
        if: ${{ steps.scope.outputs.full == 'true' }}
        run: node scripts/evals/backend-runner.mjs
        env:
          EVAL_SOURCE_SHA: ${{ github.sha }}
          EVAL_OUTPUT_DIR: ${{ runner.temp }}/backend-eval-results

      # Stage a real 110 MiB folder on its own. Running it beside the unit suite
      # can starve time-sensitive socket tests, especially under ASan.
      - name: Run large-folder enqueue regression
        if: ${{ steps.scope.outputs.full == 'true' }}
        shell: bash
        run: |
          set -o pipefail
          large_folder_status=0
          cargo test --locked -p mesh-talk-core --test large_directory_enqueue large_directory_enqueue_uses_compact_manifest_instead_of_frame_error -- --exact --ignored --test-threads=1 2> "$RUNNER_TEMP/backend-eval-results/large-folder.stderr.log" | tee "$RUNNER_TEMP/backend-eval-results/large-folder.log" || large_folder_status=$?
          cat "$RUNNER_TEMP/backend-eval-results/large-folder.stderr.log" >&2
          if (( large_folder_status != 0 )); then exit "$large_folder_status"; fi
          node scripts/evals/backend-runner.mjs --validate-large-folder "$RUNNER_TEMP/backend-eval-results/large-folder.log"

      - name: Preserve backend evaluation evidence
        if: ${{ steps.scope.outputs.full == 'true' && (always()) }}
        uses: actions/upload-artifact@v7
        with:
          name: backend-core-${{ matrix.os }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/backend-eval-results/
          if-no-files-found: error
          retention-days: 14

  native-core:
    if: ${{ !cancelled() }}
    needs: [scope]
    uses: ./.github/workflows/hidden-contacts-native.yml
    with:
      full: ${{ needs.scope.outputs.full }}
      upstream_result: ${{ needs.scope.result }}
"}

