    manifest.schema,
    manifestSchema(profile, fixtureRuntime),
    "Unsupported archive manifest",
  );
  verifyIdentity(
    manifest.identity,
    await identity(evidence, profile, fixtureRuntime),
  );
  assert.deepEqual(manifest.scheduling, scheduling(profile));
  if (profile.name !== "windows")
