    profile.name === "linux-workspace"
      ? await extractLinuxArchive(
          archive,
          process.cwd(),
          output,
          evidence("extract"),
        )
      : await list(
          [
            "--archive-file",
            archive,
            "--extract-to",
            process.cwd(),
            "--list-type",
            "binaries-only",
          ],
          evidence("extract"),
        );
